/** The stream's curve: PQ at 65 SDR code values (Lambent's InverseToneMap.swift `ToneParams.table`). */
internal object LambentToneCurve {
    fun table(peak: Float = 1000f, contrast: Float = 100f, middleGrey: Float = 50f): FloatArray {
        val t = LambentTrueHdrTables
        fun lerp(a: FloatArray, b: FloatArray, f: Float) = FloatArray(a.size) { a[it] + (b[it] - a[it]) * f }
        fun scaled(a: FloatArray, f: Float) = FloatArray(a.size) { a[it] * f }
        fun log2(x: Float) = (ln(x.toDouble()) / ln(2.0)).toFloat()
        val zero = FloatArray(t.base406.size)
        val blend = (ln(peak / 406.0) / ln(1000.0 / 406.0)).toFloat()
        val curve = lerp(t.base406, t.base1000, blend)
        val con = when {
            contrast < 50 -> lerp(t.con0, t.con50, contrast / 50)
            contrast < 100 -> lerp(t.con50, zero, (contrast - 50) / 50)
            contrast < 150 -> lerp(zero, t.con150, (contrast - 100) / 50)
            else -> lerp(t.con150, t.con200, (contrast - 150) / 50)
        }
        val g = log2(middleGrey / 50)
        val g25 = log2(25f / 50)
        val g10 = log2(10f / 50)
        val mid100 = lerp(t.mid100, t.mid100At1000, blend.coerceIn(0f, 1f))
        val mid = when {
            g >= 0 -> scaled(mid100, g)
            g >= g25 -> scaled(t.mid25, g / g25)
            else -> lerp(t.mid25, t.mid10, (g - g25) / (g10 - g25))
        }
        for (i in curve.indices) curve[i] = if (i == 0) 0f else (curve[i] + con[i] + mid[i]).coerceIn(0f, 1f)
        for (i in 1 until curve.size) curve[i] = maxOf(curve[i], curve[i - 1])
        return curve
    }
}
